/* Reel Carousel - Enhanced UI */
#beyond-reel {
  background: linear-gradient(135deg, #f8f9fa 0%, #ffffff 100%);
  position: relative;
  overflow: hidden;
}

#beyond-reel::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(204, 0, 0, 0.03) 0%, transparent 70%);
  animation: rotate 30s linear infinite;
}

@keyframes rotate {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.reel-carousel-container {
  overflow: hidden;
  margin: 2rem 0;
  padding: 1rem 0;
  position: relative;
  width: 100%;
}

.reel-carousel {
  display: flex;
  animation: slideLeftToRight 40s linear infinite;
  gap: 2rem;
  padding: 0.5rem 0;
  will-change: transform;
  width: max-content;
}

.reel-carousel:hover {
  animation-play-state: paused;
}

@keyframes slideLeftToRight {
  from {
    transform: translateX(0%);
  }
  to {
    transform: translateX(-50%);
  }
}

.reel-item {
  flex-shrink: 0;
  width: 320px;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.reel-item:hover {
  transform: scale(1.05);
  z-index: 10;
}

.reel-link {
  text-decoration: none;
  color: inherit;
  display: block;
}

.reel-thumbnail {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.12);
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  background: var(--white);
  border: 3px solid transparent;
}

.reel-thumbnail::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(204, 0, 0, 0.1), rgba(139, 0, 0, 0.1));
  opacity: 0;
  transition: opacity 0.4s ease;
  z-index: 1;
}

.reel-thumbnail:hover {
  transform: translateY(-10px);
  box-shadow: 0 20px 60px rgba(204, 0, 0, 0.3);
  border-color: var(--primary-color);
}

.reel-thumbnail:hover::before {
  opacity: 1;
}

.reel-category-tag {
  position: absolute;
  top: 15px;
  left: 15px;
  z-index: 10;
  padding: 8px 16px;
  border-radius: 25px;
  font-size: 0.75rem;
  font-weight: 700;
  backdrop-filter: blur(15px);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  animation: pulse 2s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.05); }
}

.reel-category-tag.trending {
  background: linear-gradient(135deg, #ff5722, #ff3d00);
  color: white;
  box-shadow: 0 4px 15px rgba(255, 87, 34, 0.4);
}

.reel-category-tag.new {
  background: linear-gradient(135deg, #4caf50, #66bb6a);
  color: white;
  box-shadow: 0 4px 15px rgba(76, 175, 80, 0.4);
}

.reel-category-tag.must_watch {
  background: linear-gradient(135deg, #ffc107, #ffb300);
